import React, { useState, useEffect } from 'react';
import styles from './JoinGamePage.module.css';

const JoinGamePage = () => {
    const [games, setGames] = useState([]);

    useEffect(() => {
        // Fetch games with status 2
        fetchGames();
    }, []);

    const fetchGames = async () => {
        // Replace this with actual API call
        const mockGames = [
            { id: 1, name: 'Game 1', players: 2, maxPlayers: 4 },
            { id: 2, name: 'Game 2', players: 3, maxPlayers: 4 },
            { id: 3, name: 'Game 3', players: 1, maxPlayers: 3 },
        ];
        setGames(mockGames);
    };

    const handleJoinGame = (gameId) => {
        // Implement join game logic here
        console.log(`Joining game ${gameId}`);
    };

    return (
        <div className={styles.joinGamePage}>
            <h2>Available Games</h2>
            <div className={styles.gamesList}>
                {games.map((game) => (
                    <div key={game.id} className={styles.gameCard}>
                        <h3>{game.name}</h3>
                        <p>Players: {game.players}/{game.maxPlayers}</p>
                        <button
                            onClick={() => handleJoinGame(game.id)}
                            disabled={game.players >= game.maxPlayers}
                        >
                            {game.players >= game.maxPlayers ? 'Full' : 'Join Game'}
                        </button>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default JoinGamePage;
